def longest_subseq_with_diff_one(arr, target_sum):
    n = len(arr)
    dp = [[0] * (target_sum + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, target_sum + 1):
            if arr[i - 1] > j:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - arr[i - 1]] + 1)
    return dp[n][target_sum]
```

