import re

def valid_date(date):
    date = date.replace('-', ' ').replace('/', ' ')
    date = date.split()
    if len(date) != 3:
        return False
    day, month, year = date
    if not re.match('^(0[1-9]|1[0-9]|2[0-9]|3[0-1])$', day) or not re.match('^(0[1-9]|1[0-9]|2[0-9]|3[0-1])$', month) or not re.match('^\d{4}$', year):
        return False
    month = int(month)
    if month < 1 or month > 12:
        return False
    if month in [1, 3, 5, 7, 8, 10, 12]:
        if int(day) < 1 or int(day) > 31:
            return False
    elif month in [4, 6, 9, 11]:
        if int(day) < 1 or int(day) > 30:
            return False
    elif month == 2:
        if int(day) < 1 or int(day) > 29:
            return False
    return True
