from collections import Counter

def rearange_string(s):
    counter = Counter(s)
    max_freq = max(counter.values())
    if max_freq > len(s) // 2:
        return None
    chars = sorted(counter.keys())
    result = []
    left, right = 0, len(s) - 1
    while left < right:
        if chars[left] != chars[right]:
            result.append(chars[left])
            result.append(chars[right])
            left += 1
            right -= 1
        else:
            left += 1
            right -= 1
    if left == right:
        result.append(chars[left])
    return ''.join(result)

