def compare_one(a, b): 
    """ 
    Create a function that takes integers, floats, or strings representing 
    real numbers, and returns the larger variable in its given variable type. 
    Return None if the values are equal. 
    Note: If a real number is represented as a string, the floating point might be . or , 

    compare_one(1, 2.5) ➞ 2.5 
    compare_one(1, "2,3") ➞ "2,3" 
    compare_one("5,1", "6") ➞ "6" 
    compare_one("1", 1) ➞ None 
    """
    if isinstance(a, str) and isinstance(b, str):
        a = a.replace(",", "").replace(".", "")
        b = b.replace(",", "").replace(".", "")
        if float(a) > float(b):
            return a
        elif float(a) < float(b):
            return b
        else:
            return None
    elif isinstance(a, str) and not isinstance(b, str):
        return compare_one(float(a), b)
    elif not isinstance(a, str) and isinstance(b, str):
        return compare_one(a, float(b))
    elif isinstance(a, str) and isinstance(b, str):
        if float(a) > float(b):
            return a
        elif float(a) < float(b):
            return b
        else:
            return None
    elif isinstance(a, float) and isinstance(b, float):
        if a > b:
            return a
        elif a < b:
            return b
        else:
            return None
    elif isinstance(a, int) and isinstance(b, int):
        if a > b:
            return a
        elif a < b:
            return b
        else:
            return None
    else:
        raise TypeError("Both inputs must be of the same type")
```

