from collections import Counter

def rearange_string(s):
    freq = Counter(s)
    max_freq = max(freq.values())
    if max_freq > len(s) // 2:
        return None
    chars = sorted(freq.keys())
    result = []
    left, right = 0, len(s) - 1
    while left < right:
        if freq[chars[left]] > 0 and freq[chars[right]] > 0:
            if chars[left] != chars[right]:
                result.append(chars[left])
                result.append(chars[right])
                freq[chars[left]] -= 1
                freq[chars[right]] -= 1
            else:
                left += 1
                right -= 1
        elif freq[chars[left]] > 0:
            result.append(chars[left])
            freq[chars[left]] -= 1
            left += 1
        else:
            result.append(chars[right])
            freq[chars[right]] -= 1
            right -= 1
    return ''.join(chars[left:] + chars[:left] if left < right else chars)

