def lps(s):
    def is_palindrome(s):
        return s == s[::-1]

    def lps_helper(s, i, j, memo):
        if (i, j) in memo:
            return memo[(i, j)]
        if i >= j:
            return 1 if is_palindrome(s[i:j+1]) else 0
        ans = 0
        for k in range(i, j):
            if s[i] == s[j] and is_palindrome(s[i+1:k]+s[k+1:j]+s[j+1:]):
                ans = max(ans, lps_helper(s, i+1, k-1, memo) + lps_helper(s, k+2, j, memo))
        memo[(i, j)] = ans
        return ans

    return lps_helper(s, 0, len(s)-1, {})

