def magic_square_test(square):
    n = len(square)
    if n % 2 != 0:
        return False
    expected_sum = sum(square[0])
    for i in range(n):
        if sum(square[i]) != expected_sum:
            return False
        expected_sum -= square[i][0]
        expected_sum += square[i][n-1]
    for i in range(n):
        if sum(square[j][i] for j in range(n)) != expected_sum:
            return False
    return True
