from typing import List


def parse_nested_parens(paren_string: str) -> List[int]:
    def max_depth(s: str) -> int:
        max_depth = 0
        current_depth = 0
        for c in s:
            if c == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif c == ')':
                current_depth -= 1
        return max_depth

    return [max_depth(s) for s in paren_string.split()]
