def pancake_sort(arr):
    n = len(arr)
    for size in range(n, 1, -1):
        max_index = arr.index(max(arr[:size]))
        if max_index != size - 1:
            if max_index == 0:
                arr[:size] = arr[:max_index + 1][::-1] + arr[max_index + 1:]
            else:
                arr[:max_index + 1] = arr[:max_index + 1][::-1] + arr[max_index + 1:]
        arr = arr[:size] + arr[size:]
    return arr
```

