from collections import deque

def minPath(grid, k):
    n = len(grid)
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    queue = deque([(i, j, grid[i][j], 1)])  # (x, y, value, steps)
    visited = set((i, j))
    result = []

    while queue:
        x, y, value, steps = queue.popleft()
        if steps == k:
            result.append(value)
            break
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and (nx, ny) not in visited:
                queue.append((nx, ny, grid[nx][ny], steps + 1))
                visited.add((nx, ny))

    for i in range(n):
        for j in range(n):
            if grid[i][j] not in result:
                for dx, dy in directions:
                    nx, ny = i + dx, j + dy
                    if 0 <= nx < n and 0 <= ny < n and (nx, ny) not in visited:
                        queue.append((nx, ny, grid[nx][ny], 1))
                        visited.add((nx, ny))

    return result
```

