def is_samepatterns(patterns, sequence):
    if len(patterns) != len(sequence):
        return False
    pattern_map = {}
    for p, s in zip(patterns, sequence):
        if s in pattern_map:
            if pattern_map[s] != p:
                return False
        else:
            if len(pattern_map) >= 2 and list(pattern_map.values())[-2:] == [p, p]:
                return False
            pattern_map[s] = p
    return True
