def find_longest_repeating_subseq(s):
    n = len(s)
    dp = [[0]*n for _ in range(n)]
    max_len = 0
    for i in range(n):
        for j in range(i+1, n):
            if s[i] == s[j]:
                if i == j:
                    dp[i][j] = 1
                else:
                    dp[i][j] = dp[i+1][j-1] + 1
                max_len = max(max_len, dp[i][j])
    return max_len
