        result = []
        i, j = 0, 0
        while i < len(left) and j < len(right):
            if left[i] >= right[j]:
                result.append(left[i])
                i += 1
            else:
                result.append(right[j])
                j += 1
        result += left[i:]
        result += right[j:]
        return result

    return len(merge_sort(arr, n)) - len(merge_sort(arr[::-1], n)) == 0

