def lps(s):
    n = len(s)
    dp = [[0]*n for _ in range(n)]
    for i in range(n-1, -1, -1):
        for j in range(i, n):
            if s[i] == s[j]:
                if j == i:
                    dp[i][j] = 1
                elif j == i + 1:
                    dp[i][j] = 2
                else:
                    dp[i][j] = max(dp[i+1][j], dp[i][j-1])
            else:
                dp[i][j] = 0
    return max(max(row) for row in dp) - 1
```

