def amicable_numbers_sum(n):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def is_amicable(num):
        sum = 0
        for i in range(1, num):
            if gcd(i, num) == 1 and i != num and i <= num * 2 and sum(i) == num:
                sum += i
                if sum == num:
                    return False
        return sum == num

    return sum(i for i in range(1, n + 1) if is_amicable(i))
```

