from collections import deque

def minPath(grid, k):
    n = len(grid)
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    values = [i * n + j + 1 for i in range(n) for j in range(n)]
    visited = set()
    queue = deque([(i, j, values[i * n + j], 1)])
    result = None
    while queue:
        x, y, val, dist = queue.popleft()
        if dist == k:
            if result is None or val < result[2]:
                result = (x, y, val)
        if (x, y) not in visited:
            visited.add((x, y))
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < n and (nx, ny) not in visited:
                    queue.append((nx, ny, values[nx * n + ny], dist + 1))
    return [values[x * n + y] for x, y in result] if result else []
```

