def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    current_group = []
    group_start = False

    for char in paren_string.replace(" ", ""):
        if char == "(":
            if group_start:
                current_group.append(char)
            else:
                group_start = True
        elif char == ")":
            if group_start:
                current_group.append(char)
                group_start = False
            else:
                current_group.append(char)
                group_start = True
        else:
            if group_start:
                current_group.append(char)
            else:
                current_group.append(char)
    
    if group_start:
        current_group.append("")
    
    result.append("".join(current_group))
    
    return result
