def amicable_numbers_sum(n):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def is_amicable(a):
        b = a // gcd(a, 1)
        return b != a and sum(i for i in range(1, b) if gcd(i, b) == 1) == a and sum(i for i in range(1, a) if gcd(i, a) == 1) == b

    return sum(i for i in range(1, n) if is_amicable(i))
