def max_sum(arr, n):
    dp = [[0]*n for _ in range(n)]
    for gap in range(1, n):
        for i in range(n-gap):
            j = i + gap
            if gap == 1:
                dp[i][j] = arr[i] + arr[j]
            else:
                dp[i][j] = arr[i] + max(dp[i+1][j], dp[i+1][j-gap])
    return max(max(row) for row in dp)
