            if gap == 0:
                dp[i][j] = 1
            elif gap == 1:
                dp[i][j] = 2 if s[i] == s[j] else 1
            else:
                dp[i][j] = dp[i+1][j-1] + 1 if s[i] == s[j] else max(dp[i+1][j], dp[i][j-1])
