from collections import Counter

def rearange_string(s):
    freq = Counter(s)
    max_freq = max(freq.values())
    if max_freq > len(s) // 2:
        return None
    queue = []
    res = list(s)
    for char, freq in freq.items():
        for _ in range(freq):
            if queue and queue[-1] == char:
                queue.pop()
            else:
                queue.append(char)
            res.insert(queue.index(char), char)
    return ''.join(res)
