def find_Nth_Digit(a, b, n):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return a * b // gcd(a, b)

    lcm_value = lcm(a, b)
    digit_count = 0
    num = 1
    while digit_count < n:
        num *= lcm_value
        digit_count = len(str(num))
    return int(str(num)[n-1])
